// Pull rows from each Sheet, tag with runway, default empty Priority → P3.
// Empty Priority cells get accepted as P3 + flagged `priorityDefaulted: true`
// so the UI can warn admins which services need explicit triage in the Sheet.
const SOURCES = [
  ['EKS TMN Sheet',  'EKS TMN'],
  ['EKS NANO Sheet', 'EKS NANO'],
  ['OCP Sheet',      'OCP'],
];

function pick(obj, candidates) {
  for (const c of candidates) {
    if (obj[c] !== undefined && obj[c] !== null && obj[c] !== '') return obj[c];
  }
  const norm = s => String(s).toLowerCase().replace(/[\s_\-]/g, '');
  const want = new Set(candidates.map(norm));
  for (const k of Object.keys(obj)) {
    if (want.has(norm(k)) && obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
  }
  return undefined;
}

const NAME_KEYS  = ['Service name', 'name', 'Service', 'service_name', 'ServiceName'];
const PRIO_KEYS  = ['Priority', 'priority', 'Pri'];
const GROUP_KEYS = ['Service group', 'serviceGroup', 'Group', 'service_group', 'ServiceGroup'];
const BU_KEYS    = ['BU', 'bu', 'Business Unit', 'business_unit'];

const result = [];
const seen   = new Set();
const debug  = {};

for (const [nodeName, runway] of SOURCES) {
  let items;
  try { items = $(nodeName).all(); }
  catch (e) {
    debug[runway] = { error: String(e.message || e) };
    continue;
  }

  let kept = 0, defaulted = 0, skippedNoName = 0, skippedBadPrio = 0, skippedDup = 0;
  const sampleKeys = items[0] ? Object.keys(items[0].json || {}) : [];

  for (const it of items) {
    const j = it.json || {};
    const name    = String(pick(j, NAME_KEYS)  ?? '').trim();
    const prioRaw = String(pick(j, PRIO_KEYS)  ?? '').trim().toUpperCase();
    const group   = String(pick(j, GROUP_KEYS) ?? '').trim();
    const bu      = String(pick(j, BU_KEYS)    ?? '').trim() || 'Truemoney';

    if (!name) { skippedNoName++; continue; }

    let prio, priorityDefaulted = false;
    if (!prioRaw) {
      prio = 'P3';
      priorityDefaulted = true;
    } else if (['P1','P2','P3'].includes(prioRaw)) {
      prio = prioRaw;
    } else {
      skippedBadPrio++; continue;
    }

    const key = runway + '||' + name;
    if (seen.has(key)) { skippedDup++; continue; }
    seen.add(key);

    result.push({ name, priority: prio, serviceGroup: group, bu, runway, priorityDefaulted });
    kept++;
    if (priorityDefaulted) defaulted++;
  }

  debug[runway] = { total: items.length, kept, defaulted, skippedNoName, skippedBadPrio, skippedDup, sampleKeys };
}

// Tail item with debug info; PHP ignores it because it has no `name`.
result.push({ _meta: 'debug', debug });

return result.map(json => ({ json }));
